insert into public.products (id, sku, type, line, family, spaces, price, compare_at, stock, giftable, best_seller, aroma_deal, is_new, sizes, features, specs, ideal, notes, name, tagline, description, img, gallery) values ('car-diffuser', 'OZ-CAR', 'car', '', null, array['car']::text[], 270, 0, 25, true, false, false, false, '[{"id":"15","ml":15,"delta":0}]'::jsonb, array['energy','timer']::text[], '[["spec.refill","Fragrance oil"],["spec.capacity","15 ml"],["spec.power","1.5 W (low energy consumption), 5 V"],["spec.dims","Ø 9 × 129 mm"],["spec.weight","314 g"],["spec.consumption","0.03 – 0.15 g/h"],["spec.material","PP + Aluminium"]]'::jsonb, '{"en":"Cars","es":"Coches","ar":"السيارات"}'::jsonb, '{"top":[],"heart":[],"base":[]}'::jsonb, '{"en":"Ozone Scents Car Diffuser","es":"Difusor para Coche Ozone Scents","ar":"ناشر أوزون سنتس للسيارة"}'::jsonb, '{"en":"Compact, low-energy scenting for your car.","es":"Aromatización compacta y de bajo consumo para tu coche.","ar":"تعطير صغير الحجم وموفّر للطاقة لسيارتك."}'::jsonb, '{"en":"A sleek aluminium car diffuser with mode and timer controls. Its 15 ml fragrance-oil bottle and 1.5 W power draw keep your car scented on every drive.","es":"Un elegante difusor de aluminio para coche con controles de modo y temporizador. Su frasco de 15 ml y su consumo de 1,5 W mantienen tu coche aromatizado en cada trayecto.","ar":"ناشر أنيق من الألمنيوم للسيارة مع أزرار للوضع والمؤقّت. زجاجة الزيت سعة 15 مل واستهلاك 1.5 واط يحافظان على عطر سيارتك في كل رحلة."}'::jsonb, 'o7', array[]::text[]) on conflict (id) do nothing;
insert into public.products (id, sku, type, line, family, spaces, price, compare_at, stock, giftable, best_seller, aroma_deal, is_new, sizes, features, specs, ideal, notes, name, tagline, description, img, gallery) values ('handy-diffuser', 'OZ-HANDY', 'portable', '', null, array['home']::text[], 280, 0, 25, true, false, false, false, '[{"id":"200","ml":200,"delta":0}]'::jsonb, array['bluetooth','quiet']::text[], '[["spec.capacity","200 ml"],["spec.voltage","1.5 V / 3 V / 5 V"],["spec.weight","0.5 kg"],["spec.noise","< 35 dBA"],["spec.connectivity","Bluetooth"]]'::jsonb, '{"en":"Bedrooms, bathrooms and small rooms","es":"Dormitorios, baños y estancias pequeñas","ar":"غرف النوم والحمّامات والغرف الصغيرة"}'::jsonb, '{"top":[],"heart":[],"base":[]}'::jsonb, '{"en":"Ozone Handy Diffuser","es":"Difusor Handy Ozone","ar":"ناشر أوزون هاندي"}'::jsonb, '{"en":"Quiet, Bluetooth-operated scenting in a compact shell.","es":"Aromatización silenciosa con Bluetooth en un formato compacto.","ar":"تعطير هادئ يعمل عبر البلوتوث بتصميم صغير."}'::jsonb, '{"en":"The Handy Diffuser holds 200 ml of oil, runs below 35 dBA and is operated over Bluetooth — an easy way to scent smaller spaces.","es":"El Difusor Handy contiene 200 ml de aceite, funciona por debajo de 35 dBA y se maneja por Bluetooth: una forma sencilla de aromatizar espacios pequeños.","ar":"يتسع ناشر هاندي لـ 200 مل من الزيت ويعمل بأقل من 35 ديسيبل ويُشغَّل عبر البلوتوث — طريقة سهلة لتعطير المساحات الصغيرة."}'::jsonb, 'o2', array[]::text[]) on conflict (id) do nothing;
insert into public.products (id, sku, type, line, family, spaces, price, compare_at, stock, giftable, best_seller, aroma_deal, is_new, sizes, features, specs, ideal, notes, name, tagline, description, img, gallery) values ('bath-diffuser', 'OZ-BATH', 'wall', '', null, array['home','office']::text[], 270, 0, 25, true, false, false, false, '[{"id":"150","ml":150,"delta":0}]'::jsonb, array['wallMount']::text[], '[["spec.capacity","150 ml"],["spec.weight","345 g"],["spec.coverage","100 – 300 m³"],["spec.mounting","Desktop or wall mounted"],["spec.workingTime","10 hours per day"]]'::jsonb, '{"en":"Washrooms and elevators","es":"Aseos y ascensores","ar":"دورات المياه والمصاعد"}'::jsonb, '{"top":[],"heart":[],"base":[]}'::jsonb, '{"en":"Ozone Bath Diffuser","es":"Difusor de Baño Ozone","ar":"ناشر أوزون للحمّام"}'::jsonb, '{"en":"Desktop or wall-mounted scenting for washrooms and lifts.","es":"Aromatización de sobremesa o pared para aseos y ascensores.","ar":"تعطير مكتبي أو جداري لدورات المياه والمصاعد."}'::jsonb, '{"en":"A soft-touch black unit that sits on a counter or mounts on the wall. It covers 100–300 m³ and is built to run 10 hours a day.","es":"Una unidad negra de tacto suave que se coloca sobre una encimera o se instala en la pared. Cubre de 100 a 300 m³ y está pensada para funcionar 10 horas al día.","ar":"وحدة سوداء ناعمة الملمس توضع على السطح أو تُثبّت على الجدار. تغطي من 100 إلى 300 م³ ومصممة للعمل 10 ساعات يوميًا."}'::jsonb, 'o3', array[]::text[]) on conflict (id) do nothing;
insert into public.products (id, sku, type, line, family, spaces, price, compare_at, stock, giftable, best_seller, aroma_deal, is_new, sizes, features, specs, ideal, notes, name, tagline, description, img, gallery) values ('love-diffuser', 'OZ-LOVE', 'wall', '', null, array['home','office']::text[], 460, 0, 25, true, false, false, false, '[{"id":"150","ml":150,"delta":0}]'::jsonb, array['wallMount']::text[], '[["spec.capacity","150 ml"],["spec.coverage","100 – 300 m³"],["spec.mounting","Wall mounted"]]'::jsonb, '{"en":"Small rooms, small corridors, kitchen & pantry","es":"Habitaciones y pasillos pequeños, cocina y despensa","ar":"الغرف والممرات الصغيرة والمطبخ وغرفة المؤن"}'::jsonb, '{"top":[],"heart":[],"base":[]}'::jsonb, '{"en":"Ozone Love Diffuser","es":"Difusor Love Ozone","ar":"ناشر أوزون لوف"}'::jsonb, '{"en":"A wall-mounted diffuser for small rooms and corridors.","es":"Un difusor de pared para habitaciones y pasillos pequeños.","ar":"ناشر جداري للغرف والممرات الصغيرة."}'::jsonb, '{"en":"The Love Diffuser mounts neatly on the wall and scents 100–300 m³ from a 150 ml bottle — ideal for small rooms, corridors, kitchens and pantries.","es":"El Difusor Love se instala en la pared y aromatiza de 100 a 300 m³ con un frasco de 150 ml: ideal para habitaciones pequeñas, pasillos, cocinas y despensas.","ar":"يُثبَّت ناشر لوف على الجدار بأناقة ويعطّر من 100 إلى 300 م³ من زجاجة سعة 150 مل — مثالي للغرف الصغيرة والممرات والمطابخ."}'::jsonb, 'o10', array[]::text[]) on conflict (id) do nothing;
insert into public.products (id, sku, type, line, family, spaces, price, compare_at, stock, giftable, best_seller, aroma_deal, is_new, sizes, features, specs, ideal, notes, name, tagline, description, img, gallery) values ('home-diffuser', 'OZ-HOME', 'hvac', '', null, array['home','office','commercial']::text[], 690, 0, 25, false, false, false, false, '[{"id":"500","ml":500,"delta":0}]'::jsonb, array['tank','wallMount']::text[], '[["spec.capacity","500 ml"],["spec.material","Metal"],["spec.weight","4.4 kg"],["spec.coverage","800 – 1,000 m² (2,000 – 2,500 m³)"],["spec.consumption","4.5 g ± 0.5 g"],["spec.mounting","Desktop, wall mounted or floor install"]]'::jsonb, '{"en":"Rooms, lobbies and offices","es":"Salas, vestíbulos y oficinas","ar":"الغرف والردهات والمكاتب"}'::jsonb, '{"top":[],"heart":[],"base":[]}'::jsonb, '{"en":"Ozone Home Diffuser","es":"Difusor Home Ozone","ar":"ناشر أوزون للمنزل"}'::jsonb, '{"en":"A metal-bodied machine for rooms, lobbies and offices.","es":"Una máquina con cuerpo metálico para salas, vestíbulos y oficinas.","ar":"جهاز بهيكل معدني للغرف والردهات والمكاتب."}'::jsonb, '{"en":"Built in metal with a 500 ml bottle, the Home Diffuser covers 800–1,000 m² and can stand on a desk, mount on a wall or install on the floor.","es":"Fabricado en metal con un frasco de 500 ml, el Difusor Home cubre de 800 a 1.000 m² y puede colocarse sobre una mesa, en la pared o en el suelo.","ar":"مصنوع من المعدن مع زجاجة سعة 500 مل، يغطي ناشر المنزل من 800 إلى 1000 م² ويمكن وضعه على المكتب أو تثبيته على الجدار أو الأرض."}'::jsonb, 'o4', array['o5']::text[]) on conflict (id) do nothing;
insert into public.products (id, sku, type, line, family, spaces, price, compare_at, stock, giftable, best_seller, aroma_deal, is_new, sizes, features, specs, ideal, notes, name, tagline, description, img, gallery) values ('max-diffuser', 'OZ-MAX', 'hvac', '', null, array['office','commercial']::text[], 680, 0, 25, false, false, false, false, '[{"id":"600","ml":600,"delta":0}]'::jsonb, array['led','tank']::text[], '[["spec.capacity","600 ml"],["spec.coverage","3,000 m³ (12,000 sq ft)"],["spec.dims","270 × 116 × 219 mm"],["spec.voltage","12 V"],["spec.power","17 W"]]'::jsonb, '{"en":"Dining areas, gyms, hospitals, small lobbies and restaurants","es":"Comedores, gimnasios, hospitales, vestíbulos pequeños y restaurantes","ar":"مناطق الطعام والصالات الرياضية والمستشفيات والردهات الصغيرة والمطاعم"}'::jsonb, '{"top":[],"heart":[],"base":[]}'::jsonb, '{"en":"Ozone Max Diffuser","es":"Difusor Max Ozone","ar":"ناشر أوزون ماكس"}'::jsonb, '{"en":"Digital-display scenting for up to 3,000 m³.","es":"Aromatización con pantalla digital para hasta 3.000 m³.","ar":"تعطير بشاشة رقمية حتى 3000 م³."}'::jsonb, '{"en":"A white machine with a digital display and mode/set controls. Its 600 ml bottle scents up to 3,000 m³ — suited to restaurants, gyms and clinics.","es":"Una máquina blanca con pantalla digital y controles de modo y ajuste. Su frasco de 600 ml aromatiza hasta 3.000 m³: ideal para restaurantes, gimnasios y clínicas.","ar":"جهاز أبيض بشاشة رقمية وأزرار للوضع والضبط. زجاجته سعة 600 مل تعطّر حتى 3000 م³ — مناسب للمطاعم والصالات الرياضية والعيادات."}'::jsonb, 'o9', array[]::text[]) on conflict (id) do nothing;
insert into public.products (id, sku, type, line, family, spaces, price, compare_at, stock, giftable, best_seller, aroma_deal, is_new, sizes, features, specs, ideal, notes, name, tagline, description, img, gallery) values ('box-diffuser', 'OZ-BOX', 'hvac', '', null, array['home','office','commercial']::text[], 790, 0, 25, false, false, false, false, '[{"id":"1000","ml":1000,"delta":0}]'::jsonb, array['app','tank']::text[], '[["spec.capacity","1,000 ml"],["spec.material","Plastic"],["spec.weight","3.9 kg"],["spec.coverage","3,000 – 4,000 m³"],["spec.power","15 W"],["spec.dims","295 × 113 × 230 mm"]]'::jsonb, '{"en":"Offices, showrooms, living rooms and corridors","es":"Oficinas, showrooms, salones y pasillos","ar":"المكاتب وصالات العرض وغرف المعيشة والممرات"}'::jsonb, '{"top":[],"heart":[],"base":[]}'::jsonb, '{"en":"Ozone Box Diffuser","es":"Difusor Box Ozone","ar":"ناشر أوزون بوكس"}'::jsonb, '{"en":"App-controlled scenting for 3,000–4,000 m³.","es":"Aromatización controlada por app para 3.000–4.000 m³.","ar":"تعطير يُتحكّم به عبر التطبيق لمساحات من 3000 إلى 4000 م³."}'::jsonb, '{"en":"The Box Diffuser pairs a 1,000 ml bottle with app control to scent 3,000–4,000 m³ — offices, showrooms, living rooms and corridors.","es":"El Difusor Box combina un frasco de 1.000 ml con control por app para aromatizar de 3.000 a 4.000 m³: oficinas, showrooms, salones y pasillos.","ar":"يجمع ناشر بوكس بين زجاجة سعة 1000 مل والتحكّم عبر التطبيق لتعطير من 3000 إلى 4000 م³ — المكاتب وصالات العرض وغرف المعيشة والممرات."}'::jsonb, 'o6', array[]::text[]) on conflict (id) do nothing;
