insert into public.products (id, sku, type, line, family, spaces, price, compare_at, stock, giftable, best_seller, aroma_deal, is_new, sizes, features, specs, ideal, notes, name, tagline, description, img, gallery) values ('tower-diffuser', 'OZ-TWR', 'tower', '', null, array['office','commercial']::text[], 890, 0, 25, false, false, false, false, '[{"id":"1000","ml":1000,"delta":0}]'::jsonb, array['tank']::text[], '[["spec.capacity","1,000 ml"],["spec.coverage","Up to 4,000 m³ (900 m²)"]]'::jsonb, '{"en":"Lobbies, gyms, hospitals and restaurants","es":"Vestíbulos, gimnasios, hospitales y restaurantes","ar":"الردهات والصالات الرياضية والمستشفيات والمطاعم"}'::jsonb, '{"top":[],"heart":[],"base":[]}'::jsonb, '{"en":"Ozone Tower","es":"Ozone Tower","ar":"أوزون تاور"}'::jsonb, '{"en":"Pure fragrance. Anytime. Anywhere.","es":"Fragancia pura. En cualquier momento y lugar.","ar":"عطر نقي. في أي وقت وأي مكان."}'::jsonb, '{"en":"A black tower with a 1,000 ml bottle that scents up to 4,000 m³ (900 m²) — for lobbies, gyms, hospitals and restaurants.","es":"Una torre negra con frasco de 1.000 ml que aromatiza hasta 4.000 m³ (900 m²): para vestíbulos, gimnasios, hospitales y restaurantes.","ar":"برج أسود بزجاجة سعة 1000 مل يعطّر حتى 4000 م³ (900 م²) — للردهات والصالات الرياضية والمستشفيات والمطاعم."}'::jsonb, 'o8', array[]::text[]) on conflict (id) do nothing;
insert into public.products (id, sku, type, line, family, spaces, price, compare_at, stock, giftable, best_seller, aroma_deal, is_new, sizes, features, specs, ideal, notes, name, tagline, description, img, gallery) values ('oil-ozone-scent', 'OZ-OIL-OZONESCENT', 'oil', 'signature', 'fresh', array['home','office','commercial']::text[], 230, 0, 50, true, false, false, false, '[{"id":"500","ml":500,"delta":0},{"id":"1000","ml":1000,"delta":90}]'::jsonb, array['plant','waterless']::text[], '[["spec.capacity","500 ml / 1,000 ml"],["spec.use","Aroma diffuser machines"],["spec.application","External use only — do not ingest"]]'::jsonb, null, '{"top":[],"heart":[],"base":[]}'::jsonb, '{"en":"Ozone Scent","es":"Ozone Scent","ar":"أوزون سنت"}'::jsonb, '{"en":"Premium aromatic diffuser oil.","es":"Aceite aromático premium para difusor.","ar":"زيت عطري فاخر للناشرات."}'::jsonb, '{"en":"Aroma Nature Oil is an environmental aromatic diffuser oil designed to create a fresh, calming, forest-like indoor atmosphere. It uses plant-based aromatic compounds to help promote a cleaner, fresher scent environment and to reduce common airborne odours.","es":"Aroma Nature Oil es un aceite aromático ambiental para difusores, creado para generar una atmósfera interior fresca, relajante y de bosque. Utiliza compuestos aromáticos de origen vegetal que ayudan a crear un ambiente más limpio y fresco y a reducir los olores comunes.","ar":"زيت أروما نيتشر هو زيت عطري بيئي للناشرات صُمّم لخلق أجواء داخلية منعشة ومريحة تشبه الغابة. يستخدم مركّبات عطرية نباتية تساعد على بيئة عطرية أنظف وأكثر انتعاشًا وتقليل الروائح الشائعة."}'::jsonb, 'oil-ozone-scent', array[]::text[]) on conflict (id) do nothing;
